package com.sumaye.restaurant.repository; import com.sumaye.restaurant.model.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*;
public interface ReservationRepository extends JpaRepository<Reservation,Long>{@Query("select r from Reservation r where r.table.id=:tableId and r.reservationDate=:date and r.status not in ('CANCELLED','COMPLETED','NO_SHOW') and r.startTime < :end and r.endTime > :start") List<Reservation> overlaps(@Param("tableId")Long tableId,@Param("date")LocalDate d,@Param("start")LocalTime s,@Param("end")LocalTime e); List<Reservation> findByBranchIdAndReservationDateOrderByStartTime(Long branchId,LocalDate date);}
